// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        vm.deal(actor, 0);
        uint256 balanceBefore = c.getBalance(actor);
        vm.prank(actor);
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 balanceAfter = c.getBalance(actor);
            assertTrue(balanceAfter == 0);
        }
    }
}
